CREATE OR REPLACE FUNCTION public.fusion_compare_dispatch_claim(p_actor_id uuid, p_call_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
